const ITERATIONS=600000;
const uuid=/^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/;
function exact(value,keys){return value!==null&&typeof value==='object'&&!Array.isArray(value)&&Object.keys(value).sort().join(',')===keys.split(' ').sort().join(',');}
function unb64(value,min,max=min){if(typeof value!=='string'||value.length>Math.ceil(max/3)*4||!/^([A-Za-z0-9+/]{4})*([A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/.test(value))throw Error('Invalid encrypted envelope');const bytes=Uint8Array.from(atob(value),v=>v.charCodeAt(0));if(bytes.length<min||bytes.length>max)throw Error('Invalid encrypted envelope');return bytes;}
function validConfig(v){try{if(!exact(v,'v vaultId memberId kdf iterations salt iv wrappedKey')||v.v!==1||!uuid.test(v.vaultId)||v.memberId!=='demo-member-a'||v.kdf!=='PBKDF2-SHA256'||v.iterations!==ITERATIONS)return false;unb64(v.salt,16);unb64(v.iv,12);unb64(v.wrappedKey,48);return true;}catch{return false;}}
function validEnvelope(v){try{if(!exact(v,'v vaultId profileId id revision iv ciphertext')||v.v!==1||![v.vaultId,v.profileId,v.id].every(x=>uuid.test(x))||!Number.isSafeInteger(v.revision)||v.revision<1)return false;unb64(v.iv,12);unb64(v.ciphertext,17,16000);return true;}catch{return false;}}


const member=v=>typeof v==='string'&&v.length>0&&v.length<=300&&!/[\u0000-\u001f\u007f]/.test(v);
function validPublicCredential(c){try{return exact(c,'v memberId publicKey fingerprint')&&c.v===2&&member(c.memberId)&&/^[a-f0-9]{64}$/.test(c.fingerprint)&&!!unb64(c.publicKey,400,500);}catch{return false;}}
function validCredential(c){try{if(!exact(c,'v memberId publicKey fingerprint salt iv wrappedPrivate iterations')||c.v!==2||!member(c.memberId)||!/^[a-f0-9]{64}$/.test(c.fingerprint)||c.iterations!==ITERATIONS)return false;unb64(c.publicKey,400,500);unb64(c.salt,16);unb64(c.iv,12);unb64(c.wrappedPrivate,1500,3000);return true;}catch{return false;}}
function validPackage(p){try{if(!exact(p,'v requestId vaultId recipientId fingerprint wrappedKey iv confirmation')||p.v!==2||!uuid.test(p.requestId)||!uuid.test(p.vaultId)||!member(p.recipientId)||!/^[a-f0-9]{64}$/.test(p.fingerprint))return false;unb64(p.wrappedKey,384);unb64(p.iv,12);unb64(p.confirmation,32,1500);return true;}catch{return false;}}
async function publicFingerprint(spki){const raw=unb64(spki,400,500),key=await crypto.subtle.importKey('spki',raw,{name:'RSA-OAEP',hash:'SHA-256'},false,['wrapKey']);if(key.algorithm.modulusLength!==3072)throw Error('Unsupported public key');return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',raw)),b=>b.toString(16).padStart(2,'0')).join('');}



const profiles=Array.from({length:5},(_,i)=>`${i+1}1111111-1111-4111-a111-111111111111`);
const expectedOrigin='https://homebase-vault-demo.carl-jeff.chatgpt.site',idle=120000,lifetime=600000;
const hex=bytes=>Array.from(new Uint8Array(bytes),b=>b.toString(16).padStart(2,'0')).join('');
const digest=async s=>hex(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s)));
const token=()=>hex(crypto.getRandomValues(new Uint8Array(32)));
const publicCredential=c=>({v:c.v,memberId:c.memberId,publicKey:c.publicKey,fingerprint:c.fingerprint});
const securityHeaders={'Cache-Control':'private, no-store','Pragma':'no-cache','X-Content-Type-Options':'nosniff','X-Frame-Options':'DENY','Cross-Origin-Resource-Policy':'same-origin','Referrer-Policy':'no-referrer','Permissions-Policy':'camera=(), microphone=(), geolocation=()','Content-Security-Policy':"default-src 'none'; script-src 'self'; style-src 'self'; connect-src 'self'; frame-src 'none'; frame-ancestors 'none'; base-uri 'none'; form-action 'none'; object-src 'none'"};
async function handle(request,env,assets,now=Date.now()){
 const reply=(status,data)=>Response.json(data,{status,headers:securityHeaders});
 try{
  const url=new URL(request.url);if(url.origin!==expectedOrigin||url.search)return reply(400,{error:'Invalid demo request'});
  const user=request.headers.get('oai-authenticated-user-id'),email=request.headers.get('oai-authenticated-user-email')?.trim().toLowerCase();
  if(!user||!email||user.length>300)return reply(401,{error:'Sign in to this private demo'});
  const ownerEmail=env.VAULT_OWNER_EMAIL?.trim().toLowerCase(),secondEmail=env.VAULT_SECOND_ADULT_EMAIL?.trim().toLowerCase();
  if(!ownerEmail||!secondEmail||ownerEmail===secondEmail)return reply(503,{error:'Demo adult identities are not configured'});
  if(![ownerEmail,secondEmail].includes(email))return reply(403,{error:'Not an authorized demo adult'});
  const primary=email===ownerEmail;
  if(request.method==='GET'&&assets[url.pathname]){const asset=assets[url.pathname];return new Response(asset.body,{headers:{...securityHeaders,'Content-Type':asset.type}});}
  if(!url.pathname.startsWith('/api/'))return reply(404,{error:'Not found'});
  if(!env.DB)return reply(503,{error:'Demo storage unavailable'});
  const origin=request.headers.get('origin');if(origin&&origin!==expectedOrigin||request.headers.get('sec-fetch-site')==='cross-site'||request.method!=='GET'&&origin!==expectedOrigin)return reply(403,{error:'Origin rejected'});
  if(!['POST','GET','PUT','DELETE'].includes(request.method))return reply(405,{error:'Method rejected'});
  const minute=Math.floor(now/60000),limit=await env.DB.prepare('INSERT INTO demo_limits(owner_id,minute,used) VALUES (?,?,1) ON CONFLICT(owner_id) DO UPDATE SET minute=excluded.minute,used=CASE WHEN demo_limits.minute=excluded.minute THEN demo_limits.used+1 ELSE 1 END WHERE demo_limits.minute!=excluded.minute OR demo_limits.used<120').bind(user,minute).run();if(!limit.meta.changes)return reply(429,{error:'Try again in a minute'});
  let body=null;if(request.method!=='GET'){
   if(request.headers.get('content-type')!=='application/json'||request.headers.has('content-encoding'))return reply(415,{error:'JSON required'});
   if(Number(request.headers.get('content-length')||0)>24000)return reply(413,{error:'Request too large'});
   const reader=request.body?.getReader();if(!reader)return reply(400,{error:'JSON required'});let length=0;const chunks=[];for(;;){const {value,done}=await reader.read();if(done)break;length+=value.length;if(length>24000){await reader.cancel();return reply(413,{error:'Request too large'});}chunks.push(value);}const bytes=new Uint8Array(length);let offset=0;for(const chunk of chunks){bytes.set(chunk,offset);offset+=chunk.length;}body=JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(bytes));
  }
  if(url.pathname==='/api/login'&&request.method==='POST'){
   if(!exact(body,''))return reply(400,{error:'Do not send passwords to the demo server'});
   if(primary)await env.DB.prepare('INSERT OR IGNORE INTO demo_household(slot,owner_id) VALUES (1,?)').bind(user).run();
   const home=await env.DB.prepare('SELECT owner_id FROM demo_household WHERE slot=1').first();
   if(!home||primary&&home.owner_id!==user)return reply(403,{error:'The first adult must open the demo first'});
   await env.DB.prepare('DELETE FROM demo_sessions WHERE owner_id=? AND (last_seen<=? OR expires_at<=?)').bind(user,now-idle,now).run();
   const active=await env.DB.prepare('SELECT count(*) count FROM demo_sessions WHERE owner_id=?').bind(user).first();if(active.count>=10)return reply(429,{error:'Wait for older test sessions to expire'});
   const value=token();const issued=await env.DB.prepare('INSERT INTO demo_sessions(token_digest,owner_id,last_seen,expires_at) SELECT ?,?,?,? WHERE (SELECT count(*) FROM demo_sessions WHERE owner_id=?)<10').bind(await digest(value),user,now,now+lifetime,user).run();if(!issued.meta.changes)return reply(429,{error:'Session limit reached'});return reply(200,{token:value,memberId:user,profiles,role:primary?'first':'second'});
  }
  const value=request.headers.get('authorization')?.match(/^Bearer ([a-f0-9]{64})$/)?.[1];if(!value)return reply(401,{error:'Unlock session expired'});const hash=await digest(value);
  const session=await env.DB.prepare('UPDATE demo_sessions SET last_seen=? WHERE token_digest=? AND owner_id=? AND last_seen>? AND expires_at>?').bind(now,hash,user,now-idle,now).run();if(!session.meta.changes)return reply(401,{error:'Unlock session expired'});
  if(url.pathname==='/api/lock'&&request.method==='POST'){if(!exact(body,''))return reply(400,{error:'Invalid request'});await env.DB.batch([env.DB.prepare('DELETE FROM demo_action_proofs WHERE session_digest=? AND user_id=?').bind(hash,user),env.DB.prepare('DELETE FROM demo_sessions WHERE token_digest=? AND owner_id=?').bind(hash,user)]);return reply(200,{locked:true});}
  const home=await env.DB.prepare('SELECT owner_id FROM demo_household WHERE slot=1').first();if(!home||primary&&home.owner_id!==user)return reply(403,{error:'Household unavailable'});const owner=home.owner_id;
  const membership=await env.DB.prepare('SELECT * FROM demo_members WHERE owner_id=? AND user_id=?').bind(owner,user).first();const isMember=primary||membership?.status==='approved';
  // Recheck session and membership atomically with every previously unguarded write.
  const writeGuard="EXISTS (SELECT 1 FROM demo_sessions WHERE token_digest=? AND owner_id=? AND last_seen>? AND expires_at>?) AND (?=1 OR EXISTS (SELECT 1 FROM demo_members WHERE owner_id=? AND user_id=? AND status='approved'))",writeArgs=[hash,user,now-idle,now,primary?1:0,owner,user];
  const stored=await env.DB.prepare('SELECT config_json FROM demo_vaults WHERE owner_id=?').bind(owner).first();const config=stored?JSON.parse(stored.config_json):null;
  if(url.pathname==='/api/state'&&request.method==='GET'){
   if(!isMember)return reply(200,{config:null,records:[],canInitialize:false,role:'second',membership:membership?{status:'pending',requestId:membership.request_id,credential:JSON.parse(membership.credential_json)}:null});
   const rows=await env.DB.prepare('SELECT data_json FROM demo_records WHERE owner_id=? AND deleted=0').bind(owner).all();
   const pending=await env.DB.prepare("SELECT request_id,credential_json FROM demo_members WHERE owner_id=? AND status='pending'").bind(owner).all();
   const shared=!!await env.DB.prepare("SELECT user_id FROM demo_members WHERE owner_id=? AND status='approved' AND user_id!=?").bind(owner,owner).first();
   return reply(200,{memberId:user,shared,actionCredential:membership?.status==='approved'?JSON.parse(membership.credential_json):null,ownRequest:membership?.status==='pending'?JSON.parse(membership.credential_json):null,config:primary?config:config?{vaultId:config.vaultId}:null,records:rows.results.map(r=>JSON.parse(r.data_json)),canInitialize:primary,role:primary?'first':'second',membership:primary?null:{status:'approved',credential:JSON.parse(membership.credential_json),package:JSON.parse(membership.package_json)},requests:pending.results.filter(r=>JSON.parse(r.credential_json).memberId!==user).map(r=>({requestId:r.request_id,credential:publicCredential(JSON.parse(r.credential_json))}))});
  }
  if(primary&&url.pathname==='/api/enroll'&&!await env.DB.prepare("SELECT user_id FROM demo_members WHERE owner_id=? AND user_id!=? AND status='approved'").bind(owner,owner).first())return reply(409,{error:'Pair the second adult before enrolling the first adult action key'});
  if(url.pathname==='/api/enroll'&&request.method==='POST'){
   if(!config||!validCredential(body)||body.memberId!==user||await publicFingerprint(body.publicKey)!==body.fingerprint)return reply(400,{error:'Invalid second-adult request'});
   const result=await env.DB.prepare("INSERT OR IGNORE INTO demo_members(user_id,owner_id,request_id,credential_json,status) SELECT ?,?,?,?,'pending' WHERE EXISTS (SELECT 1 FROM demo_vaults WHERE owner_id=? AND config_json=?) AND EXISTS (SELECT 1 FROM demo_sessions WHERE token_digest=? AND owner_id=? AND expires_at>?) AND (?=1 OR NOT EXISTS (SELECT 1 FROM demo_members WHERE owner_id=? AND user_id!=?))").bind(user,owner,crypto.randomUUID(),JSON.stringify(body),owner,stored.config_json,hash,user,now,primary?1:0,owner,owner).run();return reply(result.meta.changes?201:409,result.meta.changes?{requested:true}:{error:'A request or membership already exists'});
  }
  if(!isMember)return reply(403,{error:'Explicit vault membership required'});
  if(url.pathname==='/api/approve'&&request.method==='POST'){
   if(!validPackage(body)||!config||body.vaultId!==config.vaultId)return reply(400,{error:'Invalid encrypted approval'});
   const row=await env.DB.prepare("SELECT * FROM demo_members WHERE owner_id=? AND request_id=? AND status='pending'").bind(owner,body.requestId).first();if(!row||row.user_id===user)return reply(409,{error:'Request changed'});const c=JSON.parse(row.credential_json);
   if(c.memberId!==body.recipientId||c.fingerprint!==body.fingerprint)return reply(409,{error:'Request changed'});
   const result=await env.DB.prepare("UPDATE demo_members SET status='approved',package_json=? WHERE owner_id=? AND request_id=? AND status='pending' AND credential_json=? AND EXISTS (SELECT 1 FROM demo_vaults WHERE owner_id=? AND config_json=?) AND "+writeGuard).bind(JSON.stringify(body),owner,body.requestId,row.credential_json,owner,stored.config_json,...writeArgs).run();return reply(result.meta.changes?200:409,result.meta.changes?{approved:true}:{error:'Request changed'});
  }
  if(url.pathname==='/api/reject'&&request.method==='POST'){if(!exact(body,'requestId')||!uuid.test(body.requestId))return reply(400,{error:'Invalid request'});const rejected=await env.DB.prepare("DELETE FROM demo_members WHERE owner_id=? AND request_id=? AND status='pending' AND "+writeGuard).bind(owner,body.requestId,...writeArgs).run();return reply(rejected.meta.changes?200:409,rejected.meta.changes?{rejected:true}:{error:'Request changed'});}
  const scopeFor=b=>b.action==='request'?'erase-request':b.action==='confirm'&&uuid.test(b.requestId)?'erase-confirm:'+b.requestId:b.action==='delete'&&uuid.test(b.requestId)&&Number.isSafeInteger(b.revision)&&b.revision>0?'record-delete:'+b.requestId+':'+b.revision:null;
  if(url.pathname==='/api/action-challenge'&&request.method==='POST'){
   const scope=scopeFor(body??{});if(!scope||!exact(body,body.action==='request'?'action':body.action==='confirm'?'action requestId':'action requestId revision'))return reply(400,{error:'Invalid action'});
   if(!config||membership?.status!=='approved')return reply(409,{error:'Both adults must approve individual action keys first'});
   const c=JSON.parse(membership.credential_json),id=crypto.randomUUID(),expiresAt=now+60000,secret=crypto.getRandomValues(new Uint8Array(32));
   const challenge={v:1,id,vaultId:config.vaultId,memberId:user,fingerprint:c.fingerprint,scope,expiresAt};
   const label=new TextEncoder().encode(JSON.stringify(['demo-action-proof',1,id,challenge.vaultId,user,c.fingerprint,scope,expiresAt]));
   const pub=await crypto.subtle.importKey('spki',Uint8Array.from(atob(c.publicKey),x=>x.charCodeAt(0)),{name:'RSA-OAEP',hash:'SHA-256'},false,['encrypt']);
   try{challenge.ciphertext=btoa(String.fromCharCode(...new Uint8Array(await crypto.subtle.encrypt({name:'RSA-OAEP',label},pub,secret))));
    const responseDigest=await digest(btoa(String.fromCharCode(...secret)));
    await env.DB.prepare('DELETE FROM demo_action_proofs WHERE user_id=? AND (expires_at<=? OR session_digest=?)').bind(user,now,hash).run();
    const saved=await env.DB.prepare('INSERT INTO demo_action_proofs(id,owner_id,user_id,session_digest,credential_json,scope,vault_id,response_digest,expires_at) SELECT ?,?,?,?,?,?,?,?,? WHERE '+writeGuard).bind(id,owner,user,hash,membership.credential_json,scope,config.vaultId,responseDigest,expiresAt,...writeArgs).run();
    return reply(saved.meta.changes?200:409,saved.meta.changes?challenge:{error:'Authorization changed'});
   }finally{secret.fill(0);}
  }
  async function consumeProof(proof,scope){
   if(!config||membership?.status!=='approved'||!exact(proof,'id response')||!uuid.test(proof.id)||typeof proof.response!=='string'||!/^[A-Za-z0-9+/]{43}=$/.test(proof.response))return false;
   const used=await env.DB.prepare('DELETE FROM demo_action_proofs WHERE id=? AND owner_id=? AND user_id=? AND session_digest=? AND credential_json=? AND scope=? AND vault_id=? AND response_digest=? AND expires_at>? AND '+writeGuard).bind(proof.id,owner,user,hash,membership.credential_json,scope,config.vaultId,await digest(proof.response),now,...writeArgs).run();return !!used.meta.changes;
  }
  if(url.pathname==='/api/reset')return reply(409,{error:'Use the explicit erase confirmation flow'});
  if(url.pathname==='/api/erase'&&request.method==='POST'){
   if(['request','confirm'].includes(body?.action)&&!body.proof)return reply(401,{error:'Fresh vault credential proof required'});
   const second=await env.DB.prepare("SELECT user_id FROM demo_members WHERE owner_id=? AND status='approved' AND user_id!=?").bind(owner,owner).first(),shared=!!second;
   if(exact(body,'action proof')&&body.action==='request'){
    if(!await consumeProof(body.proof,'erase-request'))return reply(401,{error:'Fresh vault credential proof required'});
    const requestId=crypto.randomUUID();await env.DB.prepare('INSERT INTO demo_authorized_erase(owner_id,request_id,requested_by,expires_at) SELECT ?,?,?,? WHERE '+writeGuard+' ON CONFLICT(owner_id) DO UPDATE SET request_id=excluded.request_id,requested_by=excluded.requested_by,expires_at=excluded.expires_at WHERE demo_authorized_erase.expires_at<=?').bind(owner,requestId,user,now+600000,...writeArgs,now).run();
    const row=await env.DB.prepare('SELECT * FROM demo_authorized_erase WHERE owner_id=?').bind(owner).first();return reply(200,{requestId:row.request_id,shared,requestedByYou:row.requested_by===user,expiresAt:row.expires_at});
   }
   if(exact(body,'action requestId')&&body.action==='cancel'&&uuid.test(body.requestId)){await env.DB.prepare('DELETE FROM demo_authorized_erase WHERE owner_id=? AND request_id=? AND '+writeGuard).bind(owner,body.requestId,...writeArgs).run();return reply(200,{cancelled:true});}
   if(!exact(body,'action requestId confirm proof')||body.action!=='confirm'||!uuid.test(body.requestId)||body.confirm!==(shared?'ERASE SHARED DEMO':'ERASE DEMO'))return reply(400,{error:'Explicit erase confirmation required'});
   if(!await consumeProof(body.proof,'erase-confirm:'+body.requestId))return reply(401,{error:'Fresh vault credential proof required'});
   const row=await env.DB.prepare('SELECT * FROM demo_authorized_erase WHERE owner_id=? AND request_id=? AND expires_at>?').bind(owner,body.requestId,now).first();if(!row||shared&&row.requested_by===user)return reply(409,{error:'Both adults must confirm a shared erase'});
   const claim=token(),guard='EXISTS (SELECT 1 FROM demo_authorized_erase WHERE owner_id=? AND request_id=? AND requested_by=?)';
   const writes=[env.DB.prepare("UPDATE demo_authorized_erase SET requested_by=? WHERE owner_id=? AND request_id=? AND requested_by=? AND expires_at>? AND (SELECT count(*) FROM demo_members WHERE owner_id=? AND status='approved' AND user_id!=?)=? AND EXISTS (SELECT 1 FROM demo_sessions WHERE token_digest=? AND owner_id=? AND expires_at>?)").bind(claim,owner,body.requestId,row.requested_by,now,owner,owner,shared?1:0,hash,user,now)];
   writes.push(env.DB.prepare('DELETE FROM demo_sessions WHERE (owner_id=? OR owner_id IN (SELECT user_id FROM demo_members WHERE owner_id=?)) AND '+guard).bind(owner,owner,owner,body.requestId,claim));
   for(const table of ['demo_action_proofs','demo_members','demo_records','demo_vaults'])writes.push(env.DB.prepare('DELETE FROM '+table+' WHERE owner_id=? AND '+guard).bind(owner,owner,body.requestId,claim));
   writes.push(env.DB.prepare('DELETE FROM demo_authorized_erase WHERE owner_id=? AND request_id=? AND requested_by=?').bind(owner,body.requestId,claim));
   const erased=await env.DB.batch(writes);return reply(erased[0].meta.changes?200:409,erased[0].meta.changes?{erased:true}:{error:'Erase approval changed; no data erased'});
  }
  if(url.pathname==='/api/setup'&&request.method==='POST'){if(!primary||!validConfig(body))return reply(400,{error:'Encrypted envelope required'});const result=await env.DB.prepare('INSERT OR IGNORE INTO demo_vaults(owner_id,config_json) SELECT ?,? WHERE EXISTS (SELECT 1 FROM demo_sessions WHERE token_digest=? AND owner_id=? AND expires_at>?)').bind(owner,JSON.stringify(body),hash,user,now).run();return reply(result.meta.changes?201:409,result.meta.changes?{created:true}:{error:'Already initialized'});}
  if(url.pathname==='/api/records'&&request.method==='PUT'){
   if(!config||!validEnvelope(body)||body.vaultId!==config.vaultId||!profiles.includes(body.profileId))return reply(400,{error:'Encrypted envelope required'});
   const existing=await env.DB.prepare('SELECT id FROM demo_records WHERE owner_id=? AND id=?').bind(owner,body.id).first();if(!existing){const count=await env.DB.prepare('SELECT count(*) count FROM demo_records WHERE owner_id=?').bind(owner).first();if(count.count>=100)return reply(409,{error:'Demo record limit reached'});}
   if(!existing&&body.revision!==1)return reply(409,{error:'Refresh before editing'});
   const result=await env.DB.prepare('INSERT INTO demo_records(owner_id,id,profile_id,revision,data_json,deleted) SELECT ?,?,?,?,?,0 WHERE EXISTS (SELECT 1 FROM demo_vaults WHERE owner_id=? AND config_json=?) AND EXISTS (SELECT 1 FROM demo_sessions WHERE token_digest=? AND owner_id=? AND expires_at>?) AND (EXISTS (SELECT 1 FROM demo_records WHERE owner_id=? AND id=?) OR (SELECT count(*) FROM demo_records WHERE owner_id=?)<100) ON CONFLICT(owner_id,id) DO UPDATE SET revision=excluded.revision,data_json=excluded.data_json WHERE demo_records.deleted=0 AND demo_records.profile_id=excluded.profile_id AND demo_records.revision+1=excluded.revision').bind(owner,body.id,body.profileId,body.revision,JSON.stringify(body),owner,stored.config_json,hash,user,now,owner,body.id,owner).run();return reply(result.meta.changes?200:409,result.meta.changes?{saved:true}:{error:'Refresh before editing'});
  }
  if(url.pathname==='/api/records'&&request.method==='DELETE'){
   if(!exact(body,'id revision proof')||!uuid.test(body.id)||!Number.isSafeInteger(body.revision))return reply(400,{error:'Invalid request'});if(!await consumeProof(body.proof,'record-delete:'+body.id+':'+body.revision))return reply(401,{error:'Fresh vault credential proof required'});const result=await env.DB.prepare("UPDATE demo_records SET deleted=1,data_json='{}' WHERE owner_id=? AND id=? AND revision=? AND deleted=0 AND "+writeGuard).bind(owner,body.id,body.revision,...writeArgs).run();return reply(result.meta.changes?200:409,result.meta.changes?{deleted:true}:{error:'Refresh before deleting'});
  }
  return reply(404,{error:'Unavailable in synthetic demo'});
 }catch{return reply(400,{error:'Demo request failed safely'});}
}

const assets={"/":{"body":"<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Homebase Vault Demo</title><link rel=\"stylesheet\" href=\"/style.css\"><script type=\"module\" src=\"/client.mjs\"></script></head><body>\n<header><small>PRIVATE HOSTED DEMO · SYNTHETIC DATA ONLY</small><h1>Secure Vault</h1><p>Use only DEMO: text. No real family identifiers. This is not audited or approved for sensitive information.</p></header>\n<p id=\"status\" role=\"status\" aria-live=\"polite\">Locked</p>\n<form id=\"unlock\" autocomplete=\"off\"><p>Access is private to your ChatGPT account. The test passphrase below stays in this browser.</p><label>Independent test vault passphrase (16–256 characters)<input id=\"password\" type=\"password\" autocomplete=\"new-password\" minlength=\"16\" maxlength=\"256\" required></label><label class=\"check\"><input id=\"initialize\" type=\"checkbox\"> First use: initialize the vault or request my separate access</label><button>Unlock test vault</button></form><button id=\"reset\" type=\"button\">Start over — erase test data</button>\n<section id=\"erase-panel\" hidden><p id=\"erase-instructions\"></p><label>Erase confirmation phrase<input id=\"erase-phrase\" autocomplete=\"off\"></label><label>Your own vault passphrase<input id=\"erase-password\" type=\"password\" autocomplete=\"off\" maxlength=\"256\"></label><button id=\"erase-confirm\" type=\"button\">Confirm permanent demo erase</button><button id=\"erase-cancel\" type=\"button\">Cancel erase request</button></section>\n<section id=\"inside\" hidden><div class=\"actions\"><button id=\"lock\" type=\"button\">Lock now</button><button id=\"requests\" type=\"button\">Check access requests</button></div><label>Test family member<select id=\"profile\"></select></label><p>Each adult uses a separate account and test passphrase. Pairing needs fingerprint verification. No backups or password recovery.</p><section id=\"sharing\"></section>\n<h2>Test records</h2><div id=\"records\"></div><button id=\"add\" type=\"button\">Add test record</button>\n<form id=\"editor\" autocomplete=\"off\" hidden><h2 id=\"edit-title\">New test record</h2><label>Title<input name=\"title\" required maxlength=\"500\"></label><label>Category<select name=\"category\"><option>SSN</option><option>Passport</option><option>Birth reference</option><option>Insurance</option><option>Custom</option></select></label><label>Test value (DEMO: prefix, at most three digits)<input name=\"value\" type=\"password\" required maxlength=\"500\" autocomplete=\"new-password\"></label><label>Expiration (2099 dates only)<input name=\"expires\" type=\"date\" min=\"2099-01-01\" max=\"2099-12-31\"></label><label>Notes<textarea name=\"notes\" required maxlength=\"500\"></textarea></label><label>Physical storage location<input name=\"location\" required maxlength=\"500\"></label><div class=\"actions\"><button>Encrypt and save</button><button id=\"cancel\" type=\"button\">Cancel</button></div></form></section>\n<footer>Locks after 2 minutes without interaction, on backgrounding, and when leaving this page. Clipboard copies cannot be recalled. Encrypted test records survive page reloads in a separate demo database. Start over requires fresh credential proof. No backups or password recovery. Shared erase needs both adults. Action-key setup needs approval by the other adult.</footer></body></html>\n","type":"text/html; charset=utf-8"},"/client.mjs":{"body":"import {createVault,unlockVault,encryptRecord,decryptRecord} from './crypto.mjs';\nimport {createCredential,verifyCredential,unlockShared,approveMember,answerChallenge} from './sharing.mjs';\nimport {VaultSession} from './session.mjs';\nconst $=id=>document.getElementById(id),status=text=>{$('status').textContent=text;};\nlet plain=[],config=null,editing=null,busy=false,stateView=null,eraseTicket=null;\nconst session=new VaultSession(token=>{if(token)revoke(token);plain=[];config=null;editing=null;stateView=null;eraseTicket=null;$('sharing').replaceChildren();$('erase-panel').hidden=true;$('erase-phrase').value='';$('erase-password').value='';$('records').replaceChildren();$('editor').reset();$('editor').hidden=true;$('inside').hidden=true;$('unlock').hidden=false;$('unlock').reset();status('Locked');});\nfunction revoke(token){void fetch('/api/lock',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+token},body:'{}',cache:'no-store',credentials:'same-origin',redirect:'error',keepalive:true}).catch(()=>{});}\nfunction lock(){session.lock();}\nasync function api(path,method='GET',body,token=session.token){const response=await fetch('/api/'+path,{method,headers:{...(method==='GET'?{}:{'Content-Type':'application/json'}),...(token?{Authorization:'Bearer '+token}:{})},...(body!==undefined?{body:JSON.stringify(body)}:{}),cache:'no-store',credentials:'same-origin',redirect:'error'});if(!response.ok)throw Error(response.status===409?'Conflict: lock and unlock to refresh':response.status===401?'Membership session expired':'Request rejected; verify local membership and test data');return response.json();}\nasync function load(epoch){const state=await api('state');const next=[];for(const record of state.records){if(record.vaultId!==config.vaultId)throw Error('Record belongs to another vault');next.push({envelope:record,data:await decryptRecord(session.key,record)});}if(!session.current(epoch))return;plain=next;stateView=state;render();renderSharing();}\nfunction button(label,action){const b=document.createElement('button');b.type='button';b.textContent=label;b.onclick=action;return b;}\nfunction render(){$('records').replaceChildren();$('editor').reset();$('editor').hidden=true;editing=null;for(const record of plain.filter(r=>r.envelope.profileId===$('profile').value)){const card=document.createElement('article'),text=document.createElement('p');let revealed=false;text.textContent='•••••••• · hidden test record';const reveal=button('Reveal',()=>{session.check();if(!session.key)return;revealed=!revealed;text.textContent=revealed?`${record.data.title}\\n${record.data.category}: ${record.data.value}\\nExpiration: ${record.data.expires||'None'}\\n${record.data.notes}\\n${record.data.location}`:'•••••••• · hidden test record';reveal.textContent=revealed?'Hide':'Reveal';});const copy=button('Copy value',async()=>{session.check();if(!session.key)return;const epoch=session.epoch;try{await navigator.clipboard.writeText(record.data.value);if(session.current(epoch))status('Test value copied. Clipboard contents remain outside vault control.');}catch{if(session.current(epoch))status('Clipboard unavailable in this browser/frame.');}});const edit=button('Edit',()=>{session.check();if(session.key)editRecord(record);});const deletePassword=document.createElement('input');deletePassword.type='password';deletePassword.autocomplete='off';deletePassword.placeholder='Your own passphrase to delete';deletePassword.hidden=true;let confirming=false;const remove=button('Delete',()=>{session.check();if(!session.key)return;if(!confirming){confirming=true;deletePassword.hidden=false;deletePassword.focus();remove.textContent='Confirm delete';return;}const password=deletePassword.value;deletePassword.value='';void mutation(async epoch=>{const proof=await actionProof(password,{action:'delete',requestId:record.envelope.id,revision:record.envelope.revision},epoch);if(!session.current(epoch))return;await api('records','DELETE',{id:record.envelope.id,revision:record.envelope.revision,proof});if(session.current(epoch))await load(epoch);});});card.append(text,reveal,copy,edit,deletePassword,remove);$('records').append(card);}if(!$('records').childNodes.length)$('records').textContent='No test records for this member.';}\nfunction editRecord(record=null){editing=record?.envelope??null;$('editor').hidden=false;$('edit-title').textContent=record?'Edit test record':'New test record';const data=record?.data??{title:'DEMO: Test insurance',category:'Insurance',value:'DEMO: POLICY A',expires:'2099-12-31',notes:'DEMO: Sample only',location:'DEMO: Physical safe'};for(const [key,value]of Object.entries(data))$('editor').elements.namedItem(key).value=value;$('editor').elements.namedItem('title').focus();}\nasync function mutation(work){if(busy||!session.key)return;busy=true;const epoch=session.epoch;try{session.check();if(session.current(epoch))await work(epoch);if(session.current(epoch))status('Encrypted test records updated');}catch{if(session.current(epoch)){lock();status('Operation failed or encrypted data was invalid. Locked; unlock again to retry.');}}finally{busy=false;}}\n$('unlock').onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;const password=$('password').value,initialize=$('initialize').checked,epoch=session.begin();status('Unlocking locally…');try{const login=await api('login','POST',{},null);if(!session.current(epoch)){revoke(login.token);return;}session.token=login.token;const state=await api('state');if(!session.current(epoch))return;let key;if(state.role==='second'&&!state.membership){if(!initialize)throw Error('Select setup for your first request');const credential=await createCredential(password,login.memberId);if(!session.current(epoch))return;await api('enroll','POST',credential);if(!session.current(epoch))return;lock();status('Access requested. Compare this fingerprint outside the demo: '+credential.fingerprint);return;}if(state.membership?.status==='pending'){const fingerprint=await verifyCredential(password,state.membership.credential);if(!session.current(epoch))return;lock();status('Waiting for the other adult to approve. Your fingerprint: '+fingerprint);return;}if(state.config){config=state.config;key=state.membership?await unlockShared(password,state.membership.credential,state.membership.package):await unlockVault(password,config);}else{if(!initialize)throw Error('Select initialization for the first test');const created=await createVault(password);if(!session.current(epoch))return;config=created.config;key=created.key;await api('setup','POST',config);}if(!session.current(epoch))return;session.key=key;$('profile').replaceChildren();login.profiles.forEach((id,i)=>{const option=document.createElement('option');option.value=id;option.textContent=['Alex Demo','Robin Demo','Sam Demo','Taylor Demo','Casey Demo'][i];$('profile').append(option);});const requested=new URL(location.href).hash.slice(1);if(login.profiles.includes(requested))$('profile').value=requested;await load(epoch);if(!session.current(epoch))return;$('unlock').hidden=true;$('inside').hidden=false;status('Unlocked · synthetic data only');}catch{if(session.current(epoch)){lock();status('Unlock failed. Check your test passphrase or first-use initialization. No data was reset.');}}finally{busy=false;}};\n$('editor').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData($('editor')));void mutation(async epoch=>{const envelope=await encryptRecord(session.key,{vaultId:config.vaultId,profileId:$('profile').value,id:editing?.id??crypto.randomUUID(),revision:(editing?.revision??0)+1},data);if(!session.current(epoch))return;await api('records','PUT',envelope);if(session.current(epoch))await load(epoch);});};\n$('lock').onclick=lock;$('add').onclick=()=>{session.check();if(session.key)editRecord();};$('cancel').onclick=render;$('profile').onchange=render;\nfor(const event of ['pointerdown','keydown','touchstart'])document.addEventListener(event,()=>session.touch(),{passive:true});\ndocument.addEventListener('visibilitychange',()=>{if(document.hidden)lock();else session.check();});window.addEventListener('pagehide',lock);window.addEventListener('pageshow',()=>session.check());setInterval(()=>session.check(),1000);\n\nfunction renderSharing(){\n $('sharing').replaceChildren();\n const heading=document.createElement('h2');heading.textContent='Shared access';$('sharing').append(heading);\n if(stateView.role==='first'&&!stateView.actionCredential){\n  if(stateView.ownRequest){const form=document.createElement('form'),password=document.createElement('input'),label=document.createElement('label'),submit=document.createElement('button');password.type='password';password.autocomplete='off';label.textContent='Your vault passphrase to verify your pending fingerprint';label.append(password);submit.textContent='Verify pending action-key fingerprint';form.append(label,submit);form.onsubmit=e=>{e.preventDefault();const own=password.value;password.value='';void mutation(async epoch=>{const fingerprint=await verifyCredential(own,stateView.ownRequest);if(!session.current(epoch))return;lock();status('Share this verified action-key fingerprint outside the demo: '+fingerprint);});};$('sharing').append(form);}\n  else if(stateView.shared){const form=document.createElement('form'),password=document.createElement('input'),label=document.createElement('label'),submit=document.createElement('button');password.type='password';password.autocomplete='off';password.required=true;label.textContent='Your existing vault passphrase to enable destructive-action authorization';label.append(password);submit.textContent='Request action-key approval';form.append(label,submit);form.onsubmit=e=>{e.preventDefault();const own=password.value;password.value='';void mutation(async epoch=>{await unlockVault(own,config);const credential=await createCredential(own,stateView.memberId);if(!session.current(epoch))return;await api('enroll','POST',credential);if(session.current(epoch))await load(epoch);});};$('sharing').append(form);}\n }\n if(!stateView.requests?.length){const p=document.createElement('p');p.textContent=stateView.shared?'Both adults have equal access, each with a separate test passphrase.':'No pending requests. A second adult must sign in separately and request access with their own test passphrase.';$('sharing').append(p);return;}\n for(const request of stateView.requests){const form=document.createElement('form'),title=document.createElement('h3'),instructions=document.createElement('p'),fingerprint=document.createElement('input'),password=document.createElement('input'),submit=document.createElement('button');\n title.textContent='Approve second adult';instructions.textContent='Get the fingerprint from their device outside this demo. Paste it below and re-enter YOUR test passphrase. Never ask for their password.';\n const fingerLabel=document.createElement('label');fingerLabel.textContent='Fingerprint received from the other adult';fingerprint.required=true;fingerprint.maxLength=100;fingerLabel.append(fingerprint);\n const passLabel=document.createElement('label');passLabel.textContent='Your own test vault passphrase';password.type='password';password.autocomplete='off';password.required=true;passLabel.append(password);\n submit.textContent='Verify fingerprint and approve';form.append(title,instructions,fingerLabel,passLabel,submit);form.onsubmit=event=>{event.preventDefault();const ownPassword=password.value,checked=fingerprint.value;password.value='';void mutation(async epoch=>{const approval=await approveMember(ownPassword,stateView,request,checked);if(!session.current(epoch))return;await api('approve','POST',approval);if(session.current(epoch))await load(epoch);});};\n form.append(button('Reject request',()=>void mutation(async epoch=>{await api('reject','POST',{requestId:request.requestId});if(session.current(epoch))await load(epoch);})));$('sharing').append(form);\n }\n}\n$('requests').onclick=()=>void mutation(epoch=>load(epoch));\nasync function actionProof(password,action,epoch){\n if(!stateView?.actionCredential)throw Error('Approve your individual action key first');\n const challenge=await api('action-challenge','POST',action);const expected=action.action==='request'?'erase-request':action.action==='confirm'?'erase-confirm:'+action.requestId:'record-delete:'+action.requestId+':'+action.revision;if(challenge.scope!==expected||challenge.vaultId!==config.vaultId)throw Error('Action mismatch');if(!session.current(epoch))throw Error('Locked');\n const proof=await answerChallenge(password,stateView.actionCredential,challenge);if(!session.current(epoch))throw Error('Locked');return proof;\n}\n$('reset').onclick=()=>{session.check();if(!session.key){status('Unlock your vault first. Erase requires fresh vault credentials.');return;}if(!stateView.actionCredential){status('Enable your individual action key in Shared access first. The other adult must approve its fingerprint.');return;}eraseTicket={token:session.token};$('erase-panel').hidden=false;$('erase-instructions').textContent=stateView.shared?'Type ERASE SHARED DEMO and enter YOUR passphrase. The other adult must separately authorize the same request within 10 minutes.':'Type ERASE DEMO and enter YOUR passphrase.';$('erase-confirm').disabled=false;status('No data erased. Fresh credential proof required.');};\n$('erase-confirm').onclick=async()=>{if(busy||!eraseTicket)return;busy=true;const ticket=eraseTicket,epoch=session.epoch,password=$('erase-password').value,phrase=$('erase-phrase').value;$('erase-password').value='';session.check();try{if(!session.current(epoch))return;if(phrase!==(stateView.shared?'ERASE SHARED DEMO':'ERASE DEMO'))throw Error('Check phrase');\n const proof=await actionProof(password,{action:'request'},epoch);if(!session.current(epoch))return;const request=await api('erase','POST',{action:'request',proof},ticket.token);if(!session.current(epoch))return;eraseTicket={...request,token:ticket.token};\n if(request.shared&&request.requestedByYou){status('Request authorized. The OTHER adult must unlock, open Start over and authorize within 10 minutes.');return;}\n const confirmation=await actionProof(password,{action:'confirm',requestId:request.requestId},epoch);if(!session.current(epoch))return;await api('erase','POST',{action:'confirm',requestId:request.requestId,confirm:phrase,proof:confirmation},ticket.token);if(!session.current(epoch))return;lock();status('Demo erased. The first adult can initialize a new vault.');\n }catch{if(session.current(epoch)){lock();status('Erase not completed. Unlock and check your own passphrase, phrase and action-key approval.');}}finally{busy=false;}};\n$('erase-cancel').onclick=async()=>{if(busy||!eraseTicket)return;busy=true;const epoch=session.epoch,ticket=eraseTicket;try{session.check();if(!session.current(epoch))return;if(ticket.requestId)await api('erase','POST',{action:'cancel',requestId:ticket.requestId},ticket.token);if(session.current(epoch)){lock();status('Erase request cancelled. No data erased.');}}catch{if(session.current(epoch)){lock();status('Could not cancel. Unlock and check the current request.');}}finally{busy=false;}};\n","type":"text/javascript"},"/crypto.mjs":{"body":"// Native browser Web Crypto; no application encryption algorithm implementation.\nexport const ITERATIONS=600000;\nconst encoder=new TextEncoder(),decoder=new TextDecoder('utf-8',{fatal:true});\nexport const uuid=/^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/;\nexport function exact(value,keys){return value!==null&&typeof value==='object'&&!Array.isArray(value)&&Object.keys(value).sort().join(',')===keys.split(' ').sort().join(',');}\nexport function b64(bytes){return btoa(String.fromCharCode(...new Uint8Array(bytes)));}\nexport function unb64(value,min,max=min){if(typeof value!=='string'||value.length>Math.ceil(max/3)*4||!/^([A-Za-z0-9+/]{4})*([A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/.test(value))throw Error('Invalid encrypted envelope');const bytes=Uint8Array.from(atob(value),v=>v.charCodeAt(0));if(bytes.length<min||bytes.length>max)throw Error('Invalid encrypted envelope');return bytes;}\nconst random=n=>crypto.getRandomValues(new Uint8Array(n));\nexport function validConfig(v){try{if(!exact(v,'v vaultId memberId kdf iterations salt iv wrappedKey')||v.v!==1||!uuid.test(v.vaultId)||v.memberId!=='demo-member-a'||v.kdf!=='PBKDF2-SHA256'||v.iterations!==ITERATIONS)return false;unb64(v.salt,16);unb64(v.iv,12);unb64(v.wrappedKey,48);return true;}catch{return false;}}\nexport function validEnvelope(v){try{if(!exact(v,'v vaultId profileId id revision iv ciphertext')||v.v!==1||![v.vaultId,v.profileId,v.id].every(x=>uuid.test(x))||!Number.isSafeInteger(v.revision)||v.revision<1)return false;unb64(v.iv,12);unb64(v.ciphertext,17,16000);return true;}catch{return false;}}\nconst wrapContext=c=>encoder.encode(JSON.stringify(['homebase-synthetic-wrap',c.v,c.vaultId,c.memberId,c.kdf,c.iterations,c.salt]));\nconst recordContext=r=>encoder.encode(JSON.stringify(['homebase-synthetic-record',r.v,r.vaultId,r.profileId,r.id,r.revision]));\nexport async function wrappingKey(password,salt){if(typeof password!=='string'||password.length<16||password.length>256)throw Error('Use a test passphrase of 16–256 characters');const bytes=encoder.encode(password);try{const base=await crypto.subtle.importKey('raw',bytes,'PBKDF2',false,['deriveKey']);return await crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:ITERATIONS,hash:'SHA-256'},base,{name:'AES-GCM',length:256},false,['wrapKey','unwrapKey']);}finally{bytes.fill(0);}}\nexport async function createVault(password){const salt=random(16),iv=random(12),config={v:1,vaultId:crypto.randomUUID(),memberId:'demo-member-a',kdf:'PBKDF2-SHA256',iterations:ITERATIONS,salt:b64(salt),iv:b64(iv),wrappedKey:''};const wrapping=await wrappingKey(password,salt),temporary=await crypto.subtle.generateKey({name:'AES-GCM',length:256},true,['encrypt','decrypt']);config.wrappedKey=b64(await crypto.subtle.wrapKey('raw',temporary,wrapping,{name:'AES-GCM',iv,additionalData:wrapContext(config),tagLength:128}));return {config,key:await unlockVault(password,config)};}\nexport async function unlockVault(password,config,extractable=false){if(!validConfig(config))throw Error('Invalid encrypted envelope');const wrapping=await wrappingKey(password,unb64(config.salt,16));return crypto.subtle.unwrapKey('raw',unb64(config.wrappedKey,48),wrapping,{name:'AES-GCM',iv:unb64(config.iv,12),additionalData:wrapContext(config),tagLength:128},{name:'AES-GCM',length:256},extractable,['encrypt','decrypt']);}\nexport function validPlain(p){const text=s=>typeof s==='string'&&s.startsWith('DEMO: ')&&s.length<=500&&!/[\\u0000-\\u001f\\u007f]/.test(s);return exact(p,'title category value expires notes location')&&[p.title,p.value,p.notes,p.location].every(text)&&['SSN','Passport','Birth reference','Insurance','Custom'].includes(p.category)&&p.value.replace(/\\D/g,'').length<=3&&(p.expires===''||/^2099-\\d\\d-\\d\\d$/.test(p.expires)&&new Date(p.expires+'T00:00:00Z').toISOString().slice(0,10)===p.expires);}\nexport async function encryptRecord(key,context,plain){if(!validPlain(plain))throw Error('Use DEMO: text only; identifiers may contain at most three digits; dates must be in 2099');const iv=random(12),record={v:1,...context,iv:b64(iv),ciphertext:''};const bytes=encoder.encode(JSON.stringify(plain));try{record.ciphertext=b64(await crypto.subtle.encrypt({name:'AES-GCM',iv,additionalData:recordContext(record),tagLength:128},key,bytes));if(!validEnvelope(record))throw Error('Invalid encrypted envelope');return record;}finally{bytes.fill(0);}}\nexport async function decryptRecord(key,record){if(!validEnvelope(record))throw Error('Invalid encrypted envelope');const bytes=new Uint8Array(await crypto.subtle.decrypt({name:'AES-GCM',iv:unb64(record.iv,12),additionalData:recordContext(record),tagLength:128},key,unb64(record.ciphertext,17,16000)));try{const plain=JSON.parse(decoder.decode(bytes));if(!validPlain(plain))throw Error('Invalid test data');return plain;}finally{bytes.fill(0);}}\n","type":"text/javascript"},"/session.mjs":{"body":"// Drop keys and invalidate in-flight UI operations on lock. JavaScript cannot promise secure erasure.\nexport class VaultSession{\n constructor(clear,{clock=Date.now,idleMs=120000,lifetimeMs=600000}={}){this.clear=clear;this.clock=clock;this.idleMs=idleMs;this.lifetimeMs=lifetimeMs;this.epoch=0;this.key=null;this.token=null;this.last=0;this.started=null;}\n begin(){this.lock();this.started=this.last=this.clock();return this.epoch;}\n expired(){const now=this.clock();return this.started===null||now<this.last||now<this.started||now-this.last>=this.idleMs||now-this.started>=this.lifetimeMs;}\n current(epoch){return epoch===this.epoch&&!this.expired();}\n touch(){if(this.started===null)return;if(this.expired())this.lock();else this.last=this.clock();}\n check(){if(this.started!==null&&this.expired())this.lock();}\n lock(){const token=this.token;this.epoch++;this.key=null;this.token=null;this.last=0;this.started=null;this.clear(token);return token;}\n}\n","type":"text/javascript"},"/sharing.mjs":{"body":"import {wrappingKey,unlockVault,b64,unb64,ITERATIONS} from './crypto.mjs';\nimport {validCredential,validPublicCredential,validPackage,publicFingerprint} from './share-validation.mjs';\nconst encoder=new TextEncoder(),decoder=new TextDecoder('utf-8',{fatal:true}),random=n=>crypto.getRandomValues(new Uint8Array(n));\nexport const normalizeFingerprint=v=>v.toLowerCase().replace(/[\\s-]/g,'');\nconst credentialContext=c=>encoder.encode(JSON.stringify(['demo-rsa-credential',2,c.memberId,c.publicKey,c.fingerprint,c.salt,c.iterations]));\nconst packageContext=p=>encoder.encode(JSON.stringify(['demo-family-member',2,p.requestId,p.vaultId,p.recipientId,p.fingerprint]));\nexport async function createCredential(password,memberId){const pair=await crypto.subtle.generateKey({name:'RSA-OAEP',modulusLength:3072,publicExponent:new Uint8Array([1,0,1]),hash:'SHA-256'},true,['wrapKey','unwrapKey']);const c={v:2,memberId,publicKey:b64(await crypto.subtle.exportKey('spki',pair.publicKey)),fingerprint:'',salt:b64(random(16)),iv:b64(random(12)),wrappedPrivate:'',iterations:ITERATIONS};c.fingerprint=await publicFingerprint(c.publicKey);const kek=await wrappingKey(password,unb64(c.salt,16));c.wrappedPrivate=b64(await crypto.subtle.wrapKey('pkcs8',pair.privateKey,kek,{name:'AES-GCM',iv:unb64(c.iv,12),additionalData:credentialContext(c),tagLength:128}));if(!validCredential(c))throw Error('Invalid credential');return c;}\nasync function privateKey(password,c){if(!validCredential(c)||await publicFingerprint(c.publicKey)!==c.fingerprint)throw Error('Invalid credential');const kek=await wrappingKey(password,unb64(c.salt,16));return crypto.subtle.unwrapKey('pkcs8',unb64(c.wrappedPrivate,1500,3000),kek,{name:'AES-GCM',iv:unb64(c.iv,12),additionalData:credentialContext(c),tagLength:128},{name:'RSA-OAEP',hash:'SHA-256'},false,['unwrapKey','decrypt']);}\nexport async function verifyCredential(password,c){await privateKey(password,c);return c.fingerprint;}\nexport async function unlockShared(password,c,p,extractable=false){if(!validPackage(p)||p.recipientId!==c.memberId||p.fingerprint!==c.fingerprint)throw Error('Invalid membership');const priv=await privateKey(password,c);const key=await crypto.subtle.unwrapKey('raw',unb64(p.wrappedKey,384),priv,{name:'RSA-OAEP',label:packageContext(p)},{name:'AES-GCM',length:256},extractable,['encrypt','decrypt']);const bytes=new Uint8Array(await crypto.subtle.decrypt({name:'AES-GCM',iv:unb64(p.iv,12),additionalData:packageContext(p),tagLength:128},key,unb64(p.confirmation,32,1500)));try{if(decoder.decode(bytes)!==decoder.decode(packageContext(p)))throw Error('Invalid membership confirmation');return key;}finally{bytes.fill(0);}}\nexport async function approveMember(password,state,request,checkedFingerprint){const c=request.credential;if(!validPublicCredential(c)||normalizeFingerprint(checkedFingerprint)!==c.fingerprint||await publicFingerprint(c.publicKey)!==c.fingerprint)throw Error('Fingerprint mismatch');const key=state.membership?await unlockShared(password,state.membership.credential,state.membership.package,true):await unlockVault(password,state.config,true);const p={v:2,requestId:request.requestId,vaultId:state.config.vaultId,recipientId:c.memberId,fingerprint:c.fingerprint,wrappedKey:'',iv:b64(random(12)),confirmation:''};const pub=await crypto.subtle.importKey('spki',unb64(c.publicKey,400,500),{name:'RSA-OAEP',hash:'SHA-256'},false,['wrapKey']);p.wrappedKey=b64(await crypto.subtle.wrapKey('raw',key,pub,{name:'RSA-OAEP',label:packageContext(p)}));const bytes=packageContext(p);p.confirmation=b64(await crypto.subtle.encrypt({name:'AES-GCM',iv:unb64(p.iv,12),additionalData:bytes,tagLength:128},key,bytes));return p;}\n\n// The random proof is useful only for one actor/session/action and expires server-side.\nexport async function answerChallenge(password,credential,challenge){\n if(!challenge||challenge.v!==1||challenge.memberId!==credential.memberId||challenge.fingerprint!==credential.fingerprint||!Number.isSafeInteger(challenge.expiresAt)||Date.now()>=challenge.expiresAt)throw Error('Invalid action challenge');\n const label=encoder.encode(JSON.stringify(['demo-action-proof',1,challenge.id,challenge.vaultId,challenge.memberId,challenge.fingerprint,challenge.scope,challenge.expiresAt]));\n const key=await privateKey(password,credential),bytes=new Uint8Array(await crypto.subtle.decrypt({name:'RSA-OAEP',label},key,unb64(challenge.ciphertext,384)));\n try{if(bytes.length!==32)throw Error('Invalid action proof');return {id:challenge.id,response:b64(bytes)};}finally{bytes.fill(0);}\n}\n","type":"text/javascript"},"/share-validation.mjs":{"body":"import {exact,unb64,uuid,ITERATIONS} from './crypto.mjs';\nconst member=v=>typeof v==='string'&&v.length>0&&v.length<=300&&!/[\\u0000-\\u001f\\u007f]/.test(v);\nexport function validPublicCredential(c){try{return exact(c,'v memberId publicKey fingerprint')&&c.v===2&&member(c.memberId)&&/^[a-f0-9]{64}$/.test(c.fingerprint)&&!!unb64(c.publicKey,400,500);}catch{return false;}}\nexport function validCredential(c){try{if(!exact(c,'v memberId publicKey fingerprint salt iv wrappedPrivate iterations')||c.v!==2||!member(c.memberId)||!/^[a-f0-9]{64}$/.test(c.fingerprint)||c.iterations!==ITERATIONS)return false;unb64(c.publicKey,400,500);unb64(c.salt,16);unb64(c.iv,12);unb64(c.wrappedPrivate,1500,3000);return true;}catch{return false;}}\nexport function validPackage(p){try{if(!exact(p,'v requestId vaultId recipientId fingerprint wrappedKey iv confirmation')||p.v!==2||!uuid.test(p.requestId)||!uuid.test(p.vaultId)||!member(p.recipientId)||!/^[a-f0-9]{64}$/.test(p.fingerprint))return false;unb64(p.wrappedKey,384);unb64(p.iv,12);unb64(p.confirmation,32,1500);return true;}catch{return false;}}\nexport async function publicFingerprint(spki){const raw=unb64(spki,400,500),key=await crypto.subtle.importKey('spki',raw,{name:'RSA-OAEP',hash:'SHA-256'},false,['wrapKey']);if(key.algorithm.modulusLength!==3072)throw Error('Unsupported public key');return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',raw)),b=>b.toString(16).padStart(2,'0')).join('');}\n","type":"text/javascript"},"/style.css":{"body":":root{font-family:system-ui,sans-serif;color:#203a31;background:#f8f9f5}body{margin:0 auto;max-width:720px;padding:20px}h1{font-size:26px;margin:10px 0}h2{font-size:19px}p,footer{font-size:14px;line-height:1.6}header{border-bottom:1px solid #d3dcd3;padding-bottom:12px}header small{font-weight:700;color:#875323}label{display:grid;gap:8px;margin:18px 0}input,select,textarea,button{font:inherit;font-size:16px;box-sizing:border-box;max-width:100%;min-height:44px;border:1px solid #b4c2b6;border-radius:8px;padding:10px;background:white;color:inherit}input,select,textarea{width:100%}textarea{min-height:70px}button{cursor:pointer;margin:4px}button:disabled{opacity:.6;cursor:not-allowed}button:focus-visible,input:focus-visible{outline:3px solid #547a61}article{border:1px solid #cfd9cd;border-radius:10px;padding:14px;margin:16px 0}article p{white-space:pre-wrap;overflow-wrap:anywhere}.check{display:flex;align-items:center}.check input{width:20px;min-height:20px}.actions{display:flex;gap:6px;flex-wrap:wrap}footer{margin-top:24px;border-top:1px solid #d3dcd3;padding-top:18px;color:#5f6b61}[hidden]{display:none!important}#status{padding:10px;background:#edf1e8;border-radius:8px}\n\n#status{overflow-wrap:anywhere}#sharing form{border:1px solid #cfd9cd;border-radius:10px;padding:14px;margin:12px 0}\n","type":"text/css"}};
export default {fetch:(request,env)=>handle(request,env,assets)};
